/**
 * Confluent Cloud API-secret checksum (#209, research #234). docs.confluent.io's
 * API-key overview states that "the final 6 characters contain a Base64-encoded
 * CRC32 checksum of the prior 54 characters" and publishes, on the same page, the
 * exact secret-detection snippet: CRC32 over the 54 body characters after `cflt`
 * (prefix excluded), the 4 CRC bytes little-endian, standard Base64, first 6
 * characters. Implemented here from that description (table CRC32, IEEE
 * polynomial), independently of the fixture generator, which uses node:zlib.
 */
const CRC32_TABLE = Array.from({ length: 256 }, (_, n) => {
  let c = n;
  for (let k = 0; k < 8; k++) c = c & 1 ? 0xEDB88320 ^ (c >>> 1) : c >>> 1;
  return c >>> 0;
});
const crc32 = (text: string) => {
  let c = 0xFFFFFFFF;
  for (const byte of Buffer.from(text, 'latin1')) c = CRC32_TABLE[(c ^ byte) & 0xFF] ^ (c >>> 8);
  return (c ^ 0xFFFFFFFF) >>> 0;
};
export const confluentChecksum = (body54: string) => {
  const le = Buffer.alloc(4);
  le.writeUInt32LE(crc32(body54));
  return le.toString('base64').slice(0, 6);
};

